23	/// 应用入口。
24	///
25	/// 启动顺序：日志 → 蓝牙软初始化 → [CacheData] → [DBManager] → OSM 瓦片缓存 → [runApp]。
26	void main() {
27	  runZonedGuarded(() async {
28	    WidgetsFlutterBinding.ensureInitialized();
29	
30	    await AppLog.init();
31	
32	    FlutterError.onError = (details) {
33	      FlutterError.presentError(details);
34	      // 布局类报错（溢出、约束冲突）真正能定位问题的信息 —— 哪个控件、建在哪一行 ——
35	      // 都在 informationCollector 里，exception 本身只有一句概括。只记后者的话，
36	      // 真机日志上就只剩「overflowed by 55 pixels」，等于没线索。
37	      final info = details.informationCollector?.call();
38	      final context = details.context?.toString() ?? '';
39	      final extra = <String>[
40	        if (context.isNotEmpty) context,
41	        if (info != null) for (final node in info) node.toString(),
42	      ].join('\n');
43	      unawaited(
44	        AppLog.reportUncaught(
45	          'FlutterError',
46	          extra.isEmpty ? '${details.exception}' : '${details.exception}\n$extra',
47	          details.stack,
48	        ),
49	      );
50	    };
51	    PlatformDispatcher.instance.onError = (error, stack) {
52	      unawaited(AppLog.reportUncaught('PlatformDispatcher', error, stack));
53	      return true;
54	    };
55	
56	    FlutterBluePlus.setLogLevel(LogLevel.none);
57	    await BleManager().init();
58	    await CacheData().initInfo();
59	    await DBManager().initDB();
60	    await HelmOsmTiles.init();
61	    await AppLog.i('main', 'services ready, agreed=${CacheData().hasAgreed}');
62	
63	    // permanent: true —— 抓取进度不属于任何页面，路由怎么切都不能被回收。
64	    Get.put(TransferCenter(), permanent: true);
65	
66	    runApp(const MyApp());
67	    WidgetsBinding.instance.addPostFrameCallback((_) {
68	      unawaited(CompanionNotifRelay.instance.boot());
69	    });
70	  }, (error, stack) {
71	    unawaited(AppLog.reportUncaught('Zone', error, stack));
72	  });
73	}
