80	  @override
81	  Widget build(BuildContext context) {
82	    final debugStart = const bool.fromEnvironment('COMPANION_DEBUG');
83	    final initial = debugStart
84	        ? AppRoutes.companionDebug
85	        : (CacheData().hasAgreed ? AppRoutes.home : AppRoutes.welcome);
86	
87	    return GetMaterialApp(
88	      title: AppKeys.appName,
89	      theme: AppTheme.dark,
90	      themeMode: ThemeMode.dark,
91	      translations: AppTranslations(),
92	      locale: AppLocale.currentFromCache(),
93	      fallbackLocale: AppLocale.fallback,
94	      supportedLocales: AppLocale.supported,
95	      localizationsDelegates: const [
96	        GlobalMaterialLocalizations.delegate,
97	        GlobalWidgetsLocalizations.delegate,
98	        GlobalCupertinoLocalizations.delegate,
99	      ],
100	      initialRoute: initial,
101	      getPages: AppPages.routes,
102	      unknownRoute: AppPages.unknown,
103	      defaultTransition: Transition.cupertino,
104	      // 悬浮球挂在这一层：位于 Navigator **之上**，所以任何 push/pop
105	      // 都不会把它带走 —— 抓取中切页也能看到进度和速度。
106	      builder: (context, child) => Stack(
107	        children: [
108	          ?child,
109	          const TransferOverlay(),
110	        ],
111	      ),
112	    );
113	  }
114	}
