18	///
19	/// 默认按 Companion 约定过滤名称含 `Helm One`（及旧名 MyBike / Vela）的设备；
20	/// 可关闭过滤以列出附近全部可连接 BLE 外设。
21	class BleScanPage extends StatefulWidget {
22	  /// 创建扫描页。
23	  const BleScanPage({super.key});
24	
25	  @override
26	  State<BleScanPage> createState() => _BleScanPageState();
27	}
