29	class _BleScanPageState extends State<BleScanPage> {
30	  final Map<String, ScanResult> _devices = {};
31	  StreamSubscription<List<ScanResult>>? _scanSub;
32	  StreamSubscription<bool>? _isScanningSub;
33	  bool _scanning = false;
34	  String? _error;
35	
36	  /// 为 `true` 时仅保留名称匹配 Helm One / MyBike / Vela 的设备。
37	  bool _filterCompanion = true;
38	
39	  @override
40	  void initState() {
41	    super.initState();
42	    _isScanningSub = FlutterBluePlus.isScanning.listen((v) {
43	      if (mounted) setState(() => _scanning = v);
44	    });
45	    _startScan();
46	  }
47	
48	  @override
49	  void dispose() {
50	    _scanSub?.cancel();
51	    _isScanningSub?.cancel();
52	    BleManager().stopScan();
53	    super.dispose();
54	  }
55	
56	  /// 申请权限、确保适配器开启并开始扫描。
57	  Future<void> _startScan() async {
58	    setState(() {
59	      _error = null;
60	      _devices.clear();
61	    });
62	
63	    final ok = await BleManager().requestPermissions();
64	    if (!ok) {
65	      setState(() => _error = LocaleKeys.bleScanPermissionDenied.tr);
66	      return;
67	    }
68	
69	    if (FlutterBluePlus.adapterStateNow != BluetoothAdapterState.on) {
70	      await BleManager().turnOn();
71	      await Future<void>.delayed(const Duration(milliseconds: 500));
72	      if (FlutterBluePlus.adapterStateNow != BluetoothAdapterState.on) {
73	        setState(() => _error = LocaleKeys.bleScanTurnOnBluetooth.tr);
74	        return;
75	      }
76	    }
77	
78	    await _scanSub?.cancel();
79	    _scanSub = FlutterBluePlus.scanResults.listen((results) {
80	      if (!mounted) return;
81	      setState(() {
82	        for (final r in results) {
83	          if (!r.advertisementData.connectable) continue;
84	          final name = _deviceName(r.device);
85	          if (_filterCompanion &&
86	              !CompanionProto.matchesAdvName(name)) {
87	            continue;
88	          }
89	          _devices[r.device.remoteId.str] = r;
90	        }
91	      });
92	    }, onError: (e, st) {
93	      if (mounted) {
94	        setState(() => _error = AppTheme.failText('BleScan', e, st));
95	      }
96	    });
97	
98	    try {
99	      await FlutterBluePlus.startScan(
100	        withKeywords: _filterCompanion ? CompanionProto.scanKeywords : const [],
101	        timeout: const Duration(seconds: 15),
102	      );
103	    } catch (e, st) {
104	      if (mounted) {
105	        setState(() => _error = AppTheme.failText('BleScan', e, st));
106	      }
107	    }
108	  }
109	
110	  Future<void> _stopScan() => BleManager().stopScan();
111	
112	  String _deviceName(BluetoothDevice d) {
113	    if (d.platformName.isNotEmpty) return d.platformName;
114	    if (d.advName.isNotEmpty) return d.advName;
115	    return LocaleKeys.bleScanUnknownDevice.tr;
116	  }
117	
118	  /// 连接选中设备；成功/失败均用 [AppTheme.snack] 提示。
119	  Future<void> _connect(ScanResult result) async {
120	    await _stopScan();
121	    Get.dialog(
122	      const Center(child: CircularProgressIndicator()),
123	      barrierDismissible: false,
124	    );
125	    try {
126	      final client = CompanionClient.instance;
127	      await client.connect(result.device);
128	      if (Get.isDialogOpen ?? false) Get.back();
129	      if (client.state == CompanionConnState.ready) {
130	        await CacheData().setString(
131	          AppKeys.lastBleDeviceIdKey,
132	          result.device.remoteId.str,
133	        );
134	        CompanionNotifRelay.instance.attachIconNeed();
135	        await CompanionForegroundService.requestNotificationPermission();
136	        await CompanionForegroundService.start();
137	        AppTheme.snack(
138	          LocaleKeys.bleSnackbarTitle.tr,
139	          LocaleKeys.bleScanConnected.trParams({
140	            'name': _deviceName(result.device),
141	          }),
142	        );
143	        Get.back();
144	      } else if (client.state == CompanionConnState.versionMismatch) {
145	        AppTheme.snack(
146	          LocaleKeys.bleSnackbarTitle.tr,
147	          LocaleKeys.deviceMismatch.tr,
148	        );
149	      } else {
150	        AppTheme.snack(
151	          LocaleKeys.bleSnackbarTitle.tr,
152	          LocaleKeys.failed.tr,
153	        );
154	      }
155	    } catch (e, st) {
156	      if (Get.isDialogOpen ?? false) Get.back();
157	      AppTheme.fail(LocaleKeys.bleSnackbarTitle.tr, 'BleConnect', e, st);
158	    }
159	  }
