17	import 'package:sifli_companion/utils/cache_data.dart';
18	
19	/// 产品壳：Tab、Companion 状态、本机路书库。
20	class ShellController extends GetxController with WidgetsBindingObserver {
21	  /// 底部 Tab：0 骑行 / 1 设备 / 2 设置。
22	  final tab = 1.obs;
23	
24	  /// Companion 链路。
25	  final conn = CompanionConnState.disconnected.obs;
26	
27	  /// 最近一帧设备状态。
28	  final status = Rxn<CompanionStatus>();
29	
30	  /// 0xFF1A。
31	  final info = Rxn<CompanionDevInfo>();
32	
33	  /// 本机骑行记录条数（驱动列表刷新）。
34	  final rideTick = 0.obs;
35	
36	  /// 正在同步记录。
37	  final syncing = false.obs;
38	
39	  /// 当前同步进度；空表示未在传数据。
40	  final syncProg = Rxn<McuSyncProgress>();
41	
42	  /// 滑动窗口测得的 KB/s。
43	  final syncKbs = 0.0.obs;
44	
45	  Stopwatch? _syncSw;
46	  int _syncLastXfer = 0;
47	  int _syncLastMs = 0;
48	  DateTime _syncLastUi = DateTime.fromMillisecondsSinceEpoch(0);
49	
50	  StreamSubscription<CompanionConnState>? _stateSub;
51	  StreamSubscription<CompanionStatus>? _statusSub;
52	
53	  /// 用户点「断开」之前，后台也继续找上次的码表。
54	  bool _holdLink = true;
55	
56	  CompanionClient get client => CompanionClient.instance;
57	
58	  String get deviceName {
59	    final d = client.device;
60	    if (d == null) return '';
61	    if (d.platformName.isNotEmpty) return d.platformName;
62	    if (d.advName.isNotEmpty) return d.advName;
63	    return '';
64	  }
65	
66	  bool get isReady => conn.value == CompanionConnState.ready;
67	
68	  @override
69	  void onInit() {
70	    super.onInit();
71	    WidgetsBinding.instance.addObserver(this);
72	    conn.value = client.state;
73	    status.value = client.lastStatus;
74	    info.value = client.lastDevInfo;
75	    _stateSub = client.stateStream.listen((s) {
76	      conn.value = s;
77	      info.value = client.lastDevInfo;
78	    });
79	    _statusSub = client.statusStream.listen((s) => status.value = s);
80	    unawaited(_loadStores());
81	    unawaited(_tryReconnect());
82	  }
83	
84	  @override
85	  void onClose() {
86	    WidgetsBinding.instance.removeObserver(this);
87	    _stateSub?.cancel();
88	    _statusSub?.cancel();
89	    super.onClose();
90	  }
91	
92	  @override
93	  void didChangeAppLifecycleState(AppLifecycleState state) {
94	    switch (state) {
95	      case AppLifecycleState.resumed:
96	        unawaited(_tryReconnect());
97	      case AppLifecycleState.paused:
98	      case AppLifecycleState.hidden:
99	        unawaited(_onWentBackground());
100	      case AppLifecycleState.inactive:
101	      case AppLifecycleState.detached:
102	        break;
103	    }
104	  }
105	
106	  Future<void> _loadStores() async {
107	    await RideRecordStore().load();
108	    await NavRouteStore().load();
109	    await FavoriteStore().load();
110	    await GpxLibraryStore().load();
111	    rideTick.value++;
112	  }
113	
114	  Future<void> _onWentBackground() async {
115	    if (!_holdLink) return;
116	    await _tryReconnect();
117	    if (!CompanionForegroundService.isSupported) return;
118	    final id = await CacheData().getString(AppKeys.lastBleDeviceIdKey);
119	    if (id == null || id.isEmpty) return;
120	    // 不在这里弹通知权限：进后台时系统对话框会卡住。有权限才拉起保活。
121	    await CompanionForegroundService.start();
122	  }
123	
124	  Future<void> _tryReconnect() async {
125	    if (!_holdLink) return;
126	    if (client.isReady) {
127	      await client.refreshTimeSyncIfDue();
128	      return;
129	    }
130	    if (client.isLinking) return;
131	    if (client.device != null && client.autoReconnect) {
132	      await client.kickReconnect(resetBackoff: true);
133	      return;
134	    }
135	    final id = await CacheData().getString(AppKeys.lastBleDeviceIdKey);
136	    if (id == null || id.isEmpty) return;
137	    try {
138	      await client.connect(BluetoothDevice.fromId(id));
139	      CompanionNotifRelay.instance.attachIconNeed();
140	    } catch (e) {
141	      await AppLog.w('Shell', '自动重连失败: $e');
142	    }
143	  }
144	
145	  /// 刷新本机列表。
146	  Future<void> reloadLocal() async {
147	    await _loadStores();
148	  }
149	
150	  /// 连接成功后记住设备并拉起前台服务。
151	  Future<void> onConnected() async {
152	    _holdLink = true;
153	    final id = client.device?.remoteId.str;
154	    if (id != null) {
155	      await CacheData().setString(AppKeys.lastBleDeviceIdKey, id);
156	    }
157	    CompanionNotifRelay.instance.attachIconNeed();
158	    await CompanionForegroundService.requestNotificationPermission();
159	    await CompanionForegroundService.start();
160	  }
161	
162	  Future<void> disconnect() async {
163	    _holdLink = false;
164	    await client.disconnect();
165	  }
166	
167	  void bumpRides() => rideTick.value++;
168	
169	  /// 同步进度回调：节流刷新，并估算 KB/s。
170	  void applySyncProgress(McuSyncProgress p) {
171	    _syncSw ??= Stopwatch()..start();
172	    final ms = _syncSw!.elapsedMilliseconds;
173	    final dt = ms - _syncLastMs;
174	    if (dt >= 280) {
175	      final db = p.transferred - _syncLastXfer;
176	      if (db >= 0) {
177	        syncKbs.value = db * 1000 / (dt < 1 ? 1 : dt) / 1024;
178	      }
179	      _syncLastXfer = p.transferred;
180	      _syncLastMs = ms;
181	    }
182	    final now = DateTime.now();
183	    if (syncProg.value?.phase == p.phase &&
184	        p.done < p.total &&
185	        now.difference(_syncLastUi) < const Duration(milliseconds: 80)) {
186	      return;
187	    }
188	    _syncLastUi = now;
189	    syncProg.value = p;
190	  }
191	
192	  void clearSyncProgress() {
193	    syncing.value = false;
194	    syncProg.value = null;
195	    syncKbs.value = 0;
196	    _syncSw = null;
197	    _syncLastXfer = 0;
198	    _syncLastMs = 0;
199	  }
200	}
